      "number": 25,
      "stem": "下面有關懲罰性重貼現率 (penalty discount rate) 的敘述，正確的有幾個？甲.懲罰性重貼現是將重貼現率設定在高於市場利率的水準。乙.此時銀行不再利用重貼現放款來獲取利潤。丙.中央銀行仍然可以扮演最後貸款人的角色。丁.如此可以使宣告效果 (announcement effect) 的不確定性消失。",
